scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10) + 2;
    var str = "";
    for (var i = yyyy; i >= 1980; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_YYYY.CBData = str;
    $c.stf.setObjectValue(cmb_YYYY, ToDay.getYear());
};
scwin.fn_Search = function() {
    var vYYYY = $c.stf.getObjectValue(cmb_YYYY);
    $c.cm.ShowWin(grd_Grid);
    var url = "/SubmitStatus.do?method=listSubmitDeadline";
    //url += "&MKT_ID=" + vMKT_ID;
    url += "&BAS_YYYY=" + vYYYY;
    //url += "&BOND_YN=" + gBondYn;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
};
scwin.fn_read = function(GridID, row, colid) {
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..	

    //var vIBAS_ACNTCLS_MM = objDataID.NameString(row, "BAS_ACNTCLS_MM");

    if (row < 1) return;
    if (colid == "WRTRPT_SUBMIT_SCHDL_DD1") {
        var vIWRTRPT_SUBMIT_SCHDL_DD1 = objDataID.getCellData(row, "WRTRPT_SUBMIT_SCHDL_DD1");
        var vIBAS_YY1 = objDataID.getCellData(row, "BAS_YY1");
        if (vIWRTRPT_SUBMIT_SCHDL_DD1 == "") {
            return;
