//수정팝업 
scwin.fn_readForView = async function(GridID, row, gubun, vBAS_YY) {
    var CMD = "R";
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..	
    var vIBAS_ACNTCLS_MM = objDataID.getCellData(row, "BAS_ACNTCLS_MM");
    var vIGUBUN = gubun;
    if (scwin.fn_setParam(CMD, vBAS_YY, vIBAS_ACNTCLS_MM, vIGUBUN)) {
        // formal arguments
        await $c.frame.CreateDialogFrame("child01", "/dsclsrch/ULDSTF26604.gfm", "상세조회", 200, 100, 480, 190, "window");
    }
};




// paramObj Update
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.fn_HideDebugCtrls = function() {

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    //if (rowcount > 0)
    //	grd_Grid.AutoResizeAllCol(true);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "제출기한관리목록", "", "8");
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (js_svrGubun != 'dr') {
        scwin.fn_read(grd_Grid, row, colid);
    }
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.setColumnProp(grd_Grid, "STK_CO_COUNT", "Show", false);
    $c.cm.setColumnProp(grd_Grid, "KSQ_CO_COUNT", "Show", false);
    $c.cm.setColumnProp(grd_Grid, "BND_CO_COUNT", "Show", false);
    $c.cm.setColumnProp(grd_Grid, "CO_SUM_CNT", "Show", false);
    if (scwin.gBondYn == 'Y') {
        $c.cm.setColumnProp(grd_Grid, "BND_CO_COUNT", "Show", true);
    } else {
        if (scwin.gLdMktTp == '1') {
            $c.cm.setColumnProp(grd_Grid, "STK_CO_COUNT", "Show", true);
        } else if (scwin.gLdMktTp == '2') {
            $c.cm.setColumnProp(grd_Grid, "KSQ_CO_COUNT", "Show", true);
        } else if (scwin.gLdMktTp == '9') {
            $c.cm.setColumnProp(grd_Grid, "STK_CO_COUNT", "Show", true);
            $c.cm.setColumnProp(grd_Grid, "KSQ_CO_COUNT", "Show", true);
            $c.cm.setColumnProp(grd_Grid, "BND_CO_COUNT", "Show", true);
            $c.cm.setColumnProp(grd_Grid, "CO_SUM_CNT", "Show", true);
            $c.cm.setColumnProp(grd_Grid, "STK_CO_COUNT", "Name", '유가;상장회사수');
            $c.cm.setColumnProp(grd_Grid, "KSQ_CO_COUNT", "Name", '코스닥;상장회사수');
        }
    }
    var gYYYY = $c.ut.cGetToday("yyyymmdd").substring(0, 4);
    var gMemo = '※ 상장회사수는 주권에 한하며, ' + gYYYY + '년도 기준 데이터 입니다.';
    if (scwin.gBondYn == 'Y') {
        $c.cm.setColumnProp(grd_Grid, "CO_COUNT", "Name", '채권공시;법인수');
        gMemo = '※ 채권공시법인 회사수는  ' + gYYYY + '년도 기준 데이터 입니다.(채권의 경우 결산월이 여러개인 경우 결산월마다 count 됩니다.)';
    }
    $c.stf.setObjectValue(txb_memo, gMemo);
};
